import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'
const queries={
  "CURRENT_BOTH_SOURCES": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT t.src AS flagged_source,t.vid,s.id AS stock_id,s.inventory_source,s.quantity,s.reserved_quantity,s.last_action,s.last_source_ref,s.created_at,s.updated_at FROM t LEFT JOIN inventory_stock s ON s.variant_id=t.vid ORDER BY t.vid,s.inventory_source",
  "EVERY_RESERVATION_AND_ORDER": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT r.inventory_source AS src,r.variant_id AS vid,r.id AS reservation_id,r.quantity AS qty,r.status,r.created_at AS reserved_at,r.fulfilled_at,r.released_at,r.updated_at,r.reference_type,r.reference_id,o.id AS order_id,o.external_id,o.order_date,o.created_at AS order_created_at,o.shipping_status,o.shipping_date,o.order_status,o.manager_id,oi.id AS order_item_id,oi.stock_writeoff_status,oi.source_type AS item_source,oi.quantity AS item_qty,oi.inventory_obligation_origin_at FROM t JOIN inventory_reservations r ON r.inventory_source=t.src AND r.variant_id=t.vid LEFT JOIN orders o ON o.id=r.order_id LEFT JOIN order_items oi ON oi.id=r.order_item_id ORDER BY r.inventory_source,r.variant_id,r.created_at,r.id",
  "FULL_MOVEMENTS": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT m.inventory_source AS src,m.variant_id AS vid,m.id,m.movement_type,m.quantity_delta AS delta,m.quantity_after AS after,m.reference_type,m.reference_id,m.created_at,m.comment FROM t JOIN inventory_movements m ON m.inventory_source=t.src AND m.variant_id=t.vid ORDER BY m.inventory_source,m.variant_id,m.created_at,m.id",
  "FULL_COUNTS_CHECKS": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT c.inventory_source AS src,c.variant_id AS vid,c.id,c.expected_quantity AS expected,c.counted_quantity AS counted,c.difference_quantity AS diff,c.reserved_quantity AS reserved,c.check_type,c.reference_type,c.reference_id,c.checked_by,c.checked_at FROM t JOIN inventory_stock_checks c ON c.inventory_source=t.src AND c.variant_id=t.vid ORDER BY c.inventory_source,c.variant_id,c.checked_at,c.id",
  "FULL_STOCKTAKE_ITEMS": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT i.inventory_source AS src,i.variant_id AS vid,i.id,i.session_id,s.status AS session_status,s.started_at,s.completed_at,s.cancelled_at,i.opening_quantity,i.opening_reserved_quantity,i.baseline_quantity,i.counted_quantity,i.counted_at,i.status AS item_status,i.applied_quantity,i.updated_at FROM t JOIN inventory_stocktake_items i ON i.inventory_source=t.src AND i.variant_id=t.vid LEFT JOIN inventory_stocktake_sessions s ON s.id=i.session_id ORDER BY i.inventory_source,i.variant_id,s.started_at,i.id",
  "FULL_OPERATION_EVIDENCE": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT e.inventory_source AS src,e.variant_id AS vid,e.id,e.operation_type,e.operation_reference,e.tracked_physical_before,e.confirmed_operation_quantity,e.explained_quantity,e.unexplained_quantity,e.confirmed_by,e.occurred_at FROM t JOIN inventory_operation_evidence e ON e.inventory_source=t.src AND e.variant_id=t.vid ORDER BY e.inventory_source,e.variant_id,e.occurred_at,e.id",
  "MERGE_VARIANT_HISTORY": "SELECT 'variant_identity' AS merge_kind,old_variant_id AS old_id,keeper_variant_id AS keeper_id,reason AS details,merged_at AS happened FROM catalog_identity_variant_merges WHERE old_variant_id IN (551,871,1041,1084,1789,1800,212,1720,1787,1801,1241,207,1300,1444,1821,231) OR keeper_variant_id IN (551,871,1041,1084,1789,1800,212,1720,1787,1801,1241,207,1300,1444,1821,231) ORDER BY merged_at",
  "RECONCILIATION_HISTORY": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT j.inventory_source AS src,t.vid,j.request_id,j.source_variant_id,j.keeper_variant_id,j.decision_method,j.source_quantity_before,j.keeper_quantity_before,j.keeper_quantity_after,j.adjustment_quantity,j.reason,j.created_at FROM t JOIN catalog_stock_reconciliation_journal j ON j.inventory_source=t.src AND (j.source_variant_id=t.vid OR j.keeper_variant_id=t.vid) ORDER BY t.vid,j.created_at",
  "ALL_ORDER_ITEMS_HISTORY": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT t.src,t.vid,oi.id AS item_id,oi.order_id,oi.quantity,oi.source_type,oi.is_workshop,oi.stock_writeoff_status,oi.stock_quantity_before,oi.stock_quantity_after,o.order_date,o.created_at,o.shipping_status,o.shipping_date,o.order_status,oi.created_at AS item_created_at FROM t JOIN order_items oi ON oi.variant_id=t.vid AND COALESCE(oi.is_workshop,0)=0 AND oi.source_type=t.src JOIN orders o ON o.id=oi.order_id ORDER BY t.src,t.vid,o.order_date,oi.id",
  "RELATED_VARIANTS_SAME_PRODUCT_COLOR_SIZE": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT t.src,t.vid AS flagged_variant,v2.id AS related_variant,v2.product_id AS product_id,v2.color,v2.material,v2.length,v2.size_label,v2.gender,v2.is_active,s.inventory_source,s.quantity,s.reserved_quantity FROM t JOIN catalog_variants v1 ON v1.id=t.vid JOIN catalog_variants v2 ON v2.product_id=v1.product_id AND COALESCE(v2.size_label,'')=COALESCE(v1.size_label,'') AND COALESCE(v2.color,'')=COALESCE(v1.color,'') LEFT JOIN inventory_stock s ON s.variant_id=v2.id ORDER BY t.vid,v2.id,s.inventory_source LIMIT 1500",
  "BASELINE_V2": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT t.src,t.vid,s.id AS stock_id,b.legacy_quantity,b.captured_at FROM t JOIN inventory_stock s ON s.variant_id=t.vid AND s.inventory_source=t.src LEFT JOIN inventory_v2_baseline_stock b ON b.stock_id=s.id ORDER BY t.vid",
  "STOCK_MERGES": "WITH t(src,vid) AS (VALUES ('boutique',551),('boutique',871),('boutique',1041),('boutique',1084),('boutique',1789),('boutique',1800),('boutique',212),('warehouse',1720),('warehouse',1787),('warehouse',1801),('warehouse',1241),('warehouse',207),('warehouse',1300),('warehouse',1444),('warehouse',1821),('warehouse',231)) SELECT t.src,t.vid,s.id AS stock_id,cm.old_stock_id,cm.keeper_stock_id,cm.quantity_before,cm.reserved_before,cm.merged_at FROM t JOIN inventory_stock s ON s.variant_id=t.vid AND s.inventory_source=t.src JOIN catalog_cleanup_stock_merges cm ON cm.keeper_stock_id=s.id OR cm.old_stock_id=s.id ORDER BY t.vid,cm.merged_at"
};
const run=(sql)=>{
 const stmt=sql.trim().toUpperCase();
 if(!/^(SELECT|WITH)\b/.test(stmt)||/\b(UPDATE|DELETE|INSERT|ALTER|DROP|CREATE|REPLACE|PRAGMA|ATTACH|DETACH|VACUUM)\b/.test(stmt))throw Error('Read-only SQL gate rejected');
 const raw=execFileSync('npx',['wrangler','d1','execute','orders_db_prod','--remote','--config','wrangler.jsonc','--command',sql.trim(),'--json'],{encoding:'utf8',maxBuffer:16*1024*1024,timeout:120000});
 const data=JSON.parse(raw);
 if(data.some(x=>x.success!==true))throw Error('D1 SQL query failure');
 return data.flatMap(x=>x.results||[]);
};
const report={};
for (const [name,sql] of Object.entries(queries)){
 const rows=run(sql);
 report[name]=rows;
 const grouped={};
 for(const row of rows){const k=String(row.src||'global')+':'+String(row.vid??row.old_id??row.keeper_id??'n/a');(grouped[k]??=[]).push(row)}
 console.log('== '+name+' count='+rows.length+' ==');
 for(const [pair,history] of Object.entries(grouped)){
    if(name==='FULL_MOVEMENTS'||name==='EVERY_RESERVATION_AND_ORDER'||name==='FULL_COUNTS_CHECKS'||name==='FULL_STOCKTAKE_ITEMS'||name==='ALL_ORDER_ITEMS_HISTORY'){
      const preview=history.length<=35?history:[...history.slice(0,10),{NOTICE:'middle '+(history.length-20)+' events saved in full artifact'},...history.slice(-10)];
      console.log('PAIR '+name+' '+pair+' n='+history.length+' data='+JSON.stringify(preview));
    } else if(history.length<=60) console.log('PAIR '+name+' '+pair+' n='+history.length+' data='+JSON.stringify(history));
    else console.log('PAIR '+name+' '+pair+' n='+history.length+' first='+JSON.stringify(history.slice(0,10))+' last='+JSON.stringify(history.slice(-10)));
 }
}
writeFileSync('stock-forensic-phase2.json',JSON.stringify(report,null,2));
console.log('FORENSIC_PHASE2_ALL_SOURCES_COMPLETE');